begin;
create function pg_temp.q_assert(ok boolean,label text) returns void language plpgsql as $$begin
 if ok is distinct from true then raise exception 'Quality source assertion: %',label;end if;
 raise notice 'PASS %',label;
end$$;
create function pg_temp.q_error(statement text,expected text) returns void language plpgsql as $$begin
 begin execute statement;exception when others then if sqlerrm=expected then raise notice 'PASS blocked %',expected;return;end if;
 raise exception 'Expected %, got %',expected,sqlerrm;end;raise exception 'Expected failure %',expected;
end$$;
do $$declare x quality_test.fixtures;legacy quality_test.fixtures;s uuid;s2 uuid;e uuid;retry uuid;result uuid;so uuid;sl uuid;mr uuid;revision integer;picks jsonb;before numeric;other_product uuid;begin
 select * into legacy from quality_test.fixtures where name='legacy';
 perform set_config('request.jwt.claim.sub',legacy.actor_id::text,true);
 perform pg_temp.q_assert(not exists(select 1 from public.finished_goods_sources where factory_id=legacy.factory_id),'historical receipt has no invented provenance');
 perform pg_temp.q_assert((select quantity=100 from private.finished_goods_unattributed where factory_id=legacy.factory_id),'legacy balance initialized UNATTRIBUTED');
 perform public.adjust_finished_stock(legacy.factory_id,legacy.product_id,'meter',-10,'Legacy counted adjustment');
 perform pg_temp.q_assert((select on_hand=90 from public.finished_goods_balances where factory_id=legacy.factory_id),'legacy pooled outflow remains valid');
 perform quality_test.make_fixture('identified','meter',0.35,100);
 select * into x from quality_test.fixtures where name='identified';
 select id into s from public.finished_goods_sources where factory_id=x.factory_id and entry_id=x.entry_id;
 perform pg_temp.q_assert((select item_id=x.item_id and product_id=x.product_id and unit='meter' and quantity_credited=100 and quantity_available=0 from public.finished_goods_sources where id=s),'new receipt context retained but not physically attributed');
 retry:=gen_random_uuid();
 result:=public.source_stock_command(x.factory_id,'identify',jsonb_build_object('source',s,'quantity','100','label','PIPE-A-001','physically_identified',true),'[]',retry);
 perform pg_temp.q_assert(result=public.source_stock_command(x.factory_id,'identify',jsonb_build_object('source',s,'quantity','100','label','PIPE-A-001','physically_identified',true),'[]',retry),'identification retry same result');
 perform pg_temp.q_assert((select on_hand=100 from public.finished_goods_balances where factory_id=x.factory_id),'physical identification never credits twice');
 perform pg_temp.q_assert((select quantity_available=100 from public.finished_goods_sources where id=s),'counted source quantity retained');
 perform pg_temp.q_error(format('select public.adjust_finished_stock(%L,%L,''meter'',-1,''No physical pick'')',x.factory_id,x.product_id),'source_selection_required');
 picks:=jsonb_build_array(jsonb_build_object('source_id',s,'quantity','10'));
 retry:=gen_random_uuid();result:=public.source_stock_command(x.factory_id,'adjust',jsonb_build_object('product',x.product_id,'unit','meter','quantity','-10','reason','Physical counted loss'),picks,retry);
 perform pg_temp.q_assert(result=public.source_stock_command(x.factory_id,'adjust',jsonb_build_object('product',x.product_id,'unit','meter','quantity','-10','reason','Physical counted loss'),picks,retry),'stock debit retry exactly once');
 perform pg_temp.q_assert((select quantity_available=90 from public.finished_goods_sources where id=s),'explicit stock adjustment debits selected source');
 e:=(public.record_lean_production(x.factory_id,jsonb_build_object('unit_kind','line','production_unit',x.line_id,'item',x.item_id,'technician',x.technician_id,'good',100,'discarded_quantity',0,'scrap_kg',0,'unfinished',0,'input_quantity',0),gen_random_uuid())->>'id')::uuid;
 select id into s2 from public.finished_goods_sources where entry_id=e;
 perform public.source_stock_command(x.factory_id,'identify',jsonb_build_object('source',s2,'quantity','100','label','PIPE-A-002','physically_identified',true),'[]',gen_random_uuid());
 so:=public.create_sales_order(x.factory_id,jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('product_id',x.product_id,'quantity',30,'unit','meter'))));
 perform public.approve_sales_order(x.factory_id,so);select id into sl from public.sales_order_lines where order_id=so;
 perform public.source_stock_command(x.factory_id,'reserve',jsonb_build_object('sales_line_id',sl),jsonb_build_array(jsonb_build_object('source_id',s,'quantity','30')),gen_random_uuid());
 perform pg_temp.q_assert(private.source_reserved(x.factory_id,s)=30,'existing Sales reservation can explicitly allocate sources');
 perform pg_temp.q_error(format('select public.source_stock_command(%L,''mix'',%L::jsonb,''[]'',gen_random_uuid())',x.factory_id,jsonb_build_object('source',s,'quantity','61','physically_identified',true)::text),'source_committed');
 picks:=jsonb_build_array(jsonb_build_object('source_id',s,'quantity','10','sales_line_id',sl),jsonb_build_object('source_id',s2,'quantity','20','sales_line_id',sl));
 perform public.source_stock_command(x.factory_id,'dispatch',jsonb_build_object('sales_order',so),picks,gen_random_uuid());
 perform pg_temp.q_assert((select on_hand=160 and reserved=0 from public.finished_goods_balances where factory_id=x.factory_id),'multi-source dispatch conserves stock and reservations');
 perform pg_temp.q_assert((select quantity_available=80 from public.finished_goods_sources where id=s) and (select quantity_available=80 from public.finished_goods_sources where id=s2),'partial source dispatch retains both remaining quantities');
 perform pg_temp.q_assert(private.source_reserved(x.factory_id,s)=0,'dispatch releases physical source assignment');
 mr:=public.supply_command(x.factory_id,'material_request',jsonb_build_object('item',x.product_id,'item_type','product','quantity',20,'unit','meter','production_item_id',x.item_id),gen_random_uuid());
 select m.revision into revision from public.material_requests m where id=mr;
 perform public.source_stock_command(x.factory_id,'issue',jsonb_build_object('id',mr,'revision',revision,'reason',''),jsonb_build_array(jsonb_build_object('source_id',s,'quantity','20')),gen_random_uuid());
 perform pg_temp.q_assert((select quantity_available=60 from public.finished_goods_sources where id=s),'manufactured Product material issue preserves source');
 perform public.source_stock_command(x.factory_id,'mix',jsonb_build_object('source',s2,'quantity','10','physically_identified',true,'note','Physical identification lost in mixed bin'),'[]',gen_random_uuid());
 perform pg_temp.q_assert((select quantity=10 from private.finished_goods_unattributed where factory_id=x.factory_id),'mixed stock returns to unknown without guessing provenance');
 perform pg_temp.q_error(format('select public.source_stock_command(%L,''identify'',%L::jsonb,''[]'',gen_random_uuid())',x.factory_id,jsonb_build_object('source',s2,'quantity','10','label','PIPE-A-002','physically_identified',true)::text),'source_identity');
 perform pg_temp.q_assert((select on_hand=140 from public.finished_goods_balances where factory_id=x.factory_id),'mixing never changes physical stock');
 perform pg_temp.q_error(format('select public.source_stock_command(%L,''adjust'',%L::jsonb,%L::jsonb,gen_random_uuid())',x.factory_id,jsonb_build_object('product',x.product_id,'unit','meter','quantity','-5','reason','Wrong factory source')::text,jsonb_build_array(jsonb_build_object('source_id',gen_random_uuid(),'quantity','5'))::text),'source_unavailable');
 perform pg_temp.q_assert((select on_hand=140 from public.finished_goods_balances where factory_id=x.factory_id),'failed source transaction rolls all stock effects back');
 insert into public.products(factory_id,name,code,unit,stock_unit,unit_weight_kg) values(x.factory_id,'Other pipe','Q-OTHER','meter','meter',.4) returning id into other_product;
 so:=public.create_sales_order(x.factory_id,jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('product_id',x.product_id,'quantity',20,'unit','meter','release_when_ready',true),jsonb_build_object('product_id',other_product,'quantity',50,'unit','meter'))));
 perform public.approve_sales_order(x.factory_id,so);select id into sl from public.sales_order_lines where order_id=so and product_id=x.product_id;
 retry:=gen_random_uuid();picks:=jsonb_build_array(jsonb_build_object('source_id',s,'quantity','20','sales_line_id',sl));
 result:=public.source_stock_command(x.factory_id,'dispatch',jsonb_build_object('sales_order',so,'line',sl),picks,retry);
 perform pg_temp.q_assert(result=public.source_stock_command(x.factory_id,'dispatch',jsonb_build_object('sales_order',so,'line',sl),picks,retry),'partial-order dispatch retry debits once');
 perform pg_temp.q_assert((select dispatched_quantity=20 from public.sales_order_lines where id=sl) and (select dispatched_quantity=0 from public.sales_order_lines where order_id=so and product_id=other_product) and (select status='approved' from public.sales_orders where id=so),'ready line dispatch preserves unready line and open order');
 perform pg_temp.q_assert((select on_hand=120 from public.finished_goods_balances where factory_id=x.factory_id and product_id=x.product_id) and (select quantity_available=40 from public.finished_goods_sources where id=s),'partial order conserves actual source and Product stock');
 set constraints all immediate;
end$$;
rollback;
